    border-radius:10px;
    width:15px!important;
    height: 3px!important;

}

.testimonials .swiper-pagination-bullet-active{
    outline-color:#11294B;
    outline-offset: 2px;
    outline-width: 2px;
    outline-style: solid;
    width:30px!important;
}

