a:2:{s:10:"hide_title";s:3:"yes";s:10:"custom_css";s:2199:".wp_forms label{
    font-family: var(--e-global-typography-8a91b9d-font-family), Sans-serif!important;
    font-size: var(--e-global-typography-8a91b9d-font-size)!important;
    font-weight: var(--e-global-typography-8a91b9d-font-weight)!important;
    text-transform: var(--e-global-typography-8a91b9d-text-transform)!important;
    letter-spacing: var(--e-global-typography-8a91b9d-letter-spacing)!important;
}
.wp_forms input, .wp_forms textarea, .wp_forms select{
    background-color: var(--e-global-color-secondary)!important;
    border-color: var(--e-global-color-1e8aeaa)!important;
    border-width: 1px 1px 1px 1px!important;
    border-radius: 0px 0px 0px 0px!important;
    color: var(--e-global-color-text);
        font-family: var(--e-global-typography-text-font-family), Sans-serif!important;
    font-size: var(--e-global-typography-text-font-size)!important;
    font-weight: var(--e-global-typography-text-font-weight)!important;
    text-transform: var(--e-global-typography-text-text-transform)!important;
    font-style: var(--e-global-typography-text-font-style)!important;
    min-height: 59px!important;
    padding: 7px 20px!important;
}

.wp_forms input:focus, .wp_forms textarea:focus, .wp_forms select:focus{
    box-shadow: none!important;
    outline: none!important;
}


.wp_forms .wpforms-submit{
    background-color: var(--e-global-color-accent)!important;
    color: var(--e-global-color-cc7ebd6)!important;
    border-color: var(--e-global-color-accent)!important;
    border-style: solid!important;
    border-width: 2px 2px 2px 2px!important;
    border-radius: 0px 0px 0px 0px!important;
    min-height: 59px!important;
    font-family: var(--e-global-typography-accent-font-family), Sans-serif!important;
    font-size: var(--e-global-typography-accent-font-size)!important;
    font-weight: var(--e-global-typography-accent-font-weight)!important;
    text-transform: var(--e-global-typography-accent-text-transform)!important;
    letter-spacing: var(--e-global-typography-accent-letter-spacing)!important;
}

.wp_forms input[type="tel"] {
    padding-left: 40px !important;
}




.wp_forms button[type=submit]:focus:after{
    display: none!important;
}";}
